async function loadPaymentApps(doc){ const customerId=doc?.customerId||$('#customerId').value; const inv=(await api('/api/ar/documents?type=Invoice')).filter(i=>i.customerId===customerId&&i.balance>0); $('#apps').innerHTML=`<h4>Apply to Invoices</h4><table><tr><th>Invoice</th><th>Open Balance</th><th>Applied Amount</th></tr>${inv.map(i=>`<tr><td>${i.id}</td><td>${i.balance}</td><td><input class='apply' data-id='${i.id}' type='number' value='0' min='0' max='${i.balance}'></td></tr>`).join('')}</table><p id='totals'></p>`; calcTotals(); document.querySelectorAll('.apply').forEach(i=>i.oninput=calcTotals); }
function calcTotals(){ const p=Number($('#amount')?.value||0); const t=[...document.querySelectorAll('.apply')].reduce((s,x)=>s+Number(x.value||0),0); $('#totals').textContent=`Payment Amount: ${p} | Total Applied: ${t} | Remaining Balance: ${(p-t).toFixed(2)}`; }

