function bindForm(type,doc){ const readOnly=doc?.status==='Posted'||doc?.status==='Voided'; if(readOnly){document.querySelectorAll('#docForm input,#docForm select').forEach(el=>{if(el.id!=='void')el.disabled=true;});} if($('#amount')) $('#amount').oninput=calcTotals; $('#docForm').onsubmit=async(e)=>{e.preventDefault(); const b={type,customerId:$('#customerId').value,date:$('#date').value,terms:$('#terms').value,amount:Number($('#amount').value),method:$('#method')?.value,checkNumber:$('#checkNumber')?.value}; if(type==='Payment'){ b.applications=[...document.querySelectorAll('.apply')].map(x=>({invoiceId:x.dataset.id,amount:Number(x.value||0)})).filter(a=>a.amount>0); }
 const res = doc? await api(`/api/ar/documents/${doc.id}`,{method:'PUT',body:JSON.stringify(b)}): await api('/api/ar/documents',{method:'POST',body:JSON.stringify(b)}); alert(`Saved ${res.id}`); history.pushState({},'',`/ar/doc/${res.id}`); router(); };
 $('#del').onclick=async()=>{ if(!doc) return history.pushState({},'','/ar/invoices'),router(); await api(`/api/ar/documents/${doc.id}`,{method:'DELETE'}); alert('Deleted'); history.pushState({},'',`/ar/${doc.type==='Payment'?'payments':'invoices'}`); router(); };
 $('#post').onclick=async()=>{ if(!doc){alert('Save first'); return;} await api('/api/ar/documents/post',{method:'POST',body:JSON.stringify({id:doc.id})}); alert('Posted'); router(); };
 if($('#void')) $('#void').onclick=async()=>{ await api('/api/ar/documents/void',{method:'POST',body:JSON.stringify({id:doc.id})}); alert('Voided'); router(); };
}
$('#login-form').onsubmit=async(e)=>{e.preventDefault();try{await api('/api/auth/login',{method:'POST',body:JSON.stringify({username:$('#username').value,password:$('#password').value})});$('#login-screen').classList.add('hidden');$('#app').classList.remove('hidden');router();}catch(err){$('#login-error').textContent=err.message;}};
